SELECT CASE WHEN departments.budget >= 3835000 THEN 'high' WHEN departments.budget >= 1448000 THEN 'mid' ELSE 'low' END AS budget_bucket, departments.location, SUM(employees.salary) AS total_salary FROM employees LEFT JOIN departments ON departments.id = employees.dept_id WHERE employees.is_remote GROUP BY CASE WHEN departments.budget >= 3835000 THEN 'high' WHEN departments.budget >= 1448000 THEN 'mid' ELSE 'low' END, departments.location HAVING total_salary > 530000
